def esc(value): return escape(str(value), quote=True)
def icon(name): return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+ICON[name]+'</svg>'
def button(label, href, style='primary'): return f'<a class="btn btn-{style}" href="{esc(href)}">{esc(label)}{icon("arrow")}</a>'
def h(text): return text  # Only static, author-controlled title markup enters here.
def rel(lang): return '../' if lang != 'en' else './'
def link(page): return './'+page+'.html'
def section_head(tag,title,desc=''): return f'<div class="section-heading"><div class="stack"><p class="eyebrow">{esc(tag)}</p><h2>{esc(title)}</h2></div>{("<p>"+esc(desc)+"</p>") if desc else ""}</div>'
def dashboard(c):
 cells=''.join(f'<div class="dashboard-cell"><span class="dashboard-cell-icon">{icon(ic)}</span><div><b>{esc(a)}</b><span>{esc(b)}</span></div></div>' for a,b,ic in zip(c['dash_labels'],c['dash_values'],('shop','panel','code','spark')))
 return f'<div class="dashboard"><div class="dashboard-top"><span class="dashboard-dots"><i></i><i></i><i></i></span><span>Seller Studio</span><span class="pill">{esc(c["sample_label"])}</span></div><div class="dashboard-body"><div class="dashboard-head"><div><span class="mini-kicker">POMELO COMMERCE</span><h3>{esc(c["dashboard"])}</h3></div><span class="dashboard-mark">{icon("spark")}</span></div><div class="dashboard-grid">{cells}</div><div class="dashboard-bottom"><span>{esc(c["dash_note"])}</span><span class="mini-bars"><i></i><i></i><i></i><i></i><i></i></span></div></div></div>'

def storefront(c):
 return f'<div class="storefront"><div class="storefront-top"><b>POMELO COMMERCE</b><span class="pill">{esc(c["sample_label"])}</span></div><div class="storefront-banner"><span class="mini-kicker">{esc(c["feature_names"][0])}</span><strong>{esc(c["product_title"])}</strong></div><div class="storefront-products" aria-hidden="true"><span><i class="object-vase"></i></span><span><i class="object-bowl"></i></span><span><i class="object-cup"></i></span></div><p class="dashboard-note">{esc(c["dash_note"])}</p></div>'

def brand_relation(c):
 rows=''.join(f'<div class="brand-relation-item">{icon(ic)}<span>{esc(n)}</span></div>' for ic,n in zip(("shop","code","spark"),c['service_names']))
