def hero_visual(c, variant):
 if variant=='commerce':
  chips=''.join(f'<span>{icon(ic)}{esc(label)}</span>' for ic,label in zip(('shop','panel','spark'),c['band']))
  return f'<div class="page-visual page-visual-commerce"><div class="visual-orbit"></div><div class="visual-label">{esc(c["product_kicker"])}</div>{dashboard(c)}<div class="visual-chips">{chips}</div></div>'
 if variant=='how':
  rows=''.join(f'<a class="hero-journey-row" href="#step-{i}"><span>{i:02}</span><b>{esc(n)}</b>{icon("arrow")}</a>' for i,n in enumerate(c['steps'],1))
  return f'<div class="page-visual page-visual-how"><div class="hero-journey"><p class="mini-kicker">{esc(c["journey_kicker"])}</p>{rows}</div><span class="hero-floating-mark">{icon("spark")}</span></div>'
 if variant=='services':
  rows=''.join(f'<a class="service-preview-row" href="#service-offerings"><span class="card-symbol">{icon(ic)}</span><span><b>{esc(n)}</b><small>{esc(d)}</small></span>{icon("arrow")}</a>' for n,d,ic in zip(c['services_cards'],c['services_copy'],('panel','code','spark')))
  return f'<div class="page-visual page-visual-services"><div class="service-preview"><p class="mini-kicker">{esc(c["services_kicker"])}</p>{rows}</div></div>'
 if variant=='about':
  return f'<div class="page-visual page-visual-about"><img src="{ASSET}merchant.webp" alt="" loading="eager"><div class="about-visual-note"><img src="{ASSET}pomelo-compact.svg" alt=""><div><span class="mini-kicker">{esc(c["about_kicker"])}</span><b>Pomelo STEM</b><small>{esc(c["tagline"])}</small></div></div></div>'
 if variant=='contact':
  return f'<div class="page-visual page-visual-contact"><div class="contact-visual-mark">{icon("chat")}</div><div><p class="mini-kicker">{esc(c["contact_kicker"])}</p><h2>{esc(c["whatsapp"])}</h2><p>{esc(c["whatsapp_desc"])}</p><strong>+60 11-3902 3123</strong></div></div>'
 return ''

def hero(c, tag, title, desc, art=False, variant=''):
 if variant=='contact':
  actions=button(c['whatsapp'],'https://wa.me/601139023123')+button(c['sample_contact_title'],'#sample-form','outline')
 elif variant=='commerce':
  actions=button(c['demo'],link('contact'))+button(c['tour_tag'],'#product-preview','outline')
 elif variant=='how':
  actions=button(c['demo'],link('contact'))+button(c['steps'][0],'#step-1','outline')
 else:
  actions=button(c['demo'],link('contact'))+button(c['explore'],link('commerce'),'outline')
 identity=f'<img src="{ASSET}pomelo-compact.svg" alt="" aria-hidden="true">{esc(c["brand_line"])}' if art else esc(tag)
 text=f'<div class="hero-copy"><p class="eyebrow">{identity}</p><h1>{h(title)}</h1><p>{esc(desc)}</p><div class="button-row">{actions}</div></div>'
 if variant: return f'<section class="page-hero page-hero-v2"><div class="wrap page-hero-grid">{text}{hero_visual(c,variant)}</div></section>'
 if not art: return f'<section class="page-hero"><div class="wrap">{text}</div></section>'
 art_html=f'<div class="hero-art"><img class="hero-photo" src="{ASSET}merchant.webp" alt="" fetchpriority="high"><span class="photo-label">{esc(c["examples"])}</span><div class="hero-art-caption"><span class="mini-kicker">{esc(c["story_tag"])}</span><strong>{esc(c["story_steps"][0])}</strong></div><div class="floating-card"><div class="card-head"><span>{esc(c["dashboard"])}</span><span class="pill">{esc(c["examples"])}</span></div>'+''.join(f'<div class="mock-row"><span class="mock-icon">{icon(ic)}</span><b>{esc(n)}</b><span>{esc(v)}</span></div>' for ic,n,v in zip(('shop','panel','spark'),c['dash_labels'],c['dash_values']))+'</div></div>'
 return f'<section class="hero"><div class="wrap hero-grid">{text}{art_html}</div></section>'
def cards(names,texts,icons,links=None,c=None):
 return '<div class="cards">'+''.join(f'<article class="card"><div class="card-symbol">{icon(ic)}</div><h3>{esc(name)}</h3><p>{esc(desc)}</p>'+((f'<a class="text-link" href="{esc(link(url))}">{esc(c["view"])} {icon("arrow")}</a>') if links else '')+'</article>' for name,desc,ic,url in zip(names,texts,icons,links or [None]*len(names)))+'</div>'
def steps(c, names='steps', descs='step_text'): return '<div class="steps">'+''.join(f'<article class="step"><span class="step-number">{i:02}</span><h3>{esc(n)}</h3><p>{esc(d)}</p></article>' for i,(n,d) in enumerate(zip(c[names],c[descs]),1))+'</div>'
def cta(c, contact=False): return f'<section class="section"><div class="wrap"><div class="cta"><div><h2>{esc(c["talk"])}</h2><p>{esc(c["talk_desc"])}</p></div>{button(c["whatsapp"] if contact else c["cta"],"https://wa.me/601139023123" if contact else link("contact"),"light")}</div></div></section>'
def concept_home(c):
 icons=('shop','panel','spark')
 items=''.join(f'<li><span class="home-feature-icon">{icon(ic)}</span><div><strong>{esc(title)}</strong><p>{esc(desc)}</p></div></li>' for ic,title,desc in zip(icons,c['tabs'],c['tab_desc']))
