def scenario_switch(c, index):
 items=c['scenes'][index]
 buttons='' if index == 0 else ''.join(f'<button type="button" data-scene-button="{i}" aria-pressed="{str(i==0).lower()}" aria-controls="scene-{index}-{i}">{esc(label)}</button>' for i,(label,title,body) in enumerate(items))
 panels=[]
 for i,(_,title,body) in enumerate(items):
  if index == 0:
   shape=('object-cup','object-bowl','object-basket')[i]
   detail=f'<div class="selected-product"><div class="demo-product-art art-{i}" aria-hidden="true"><i class="{shape}"></i></div><div><strong>{esc(title)}</strong><span class="demo-product-price">{esc(c["sample_prices"][i])}</span><p>{esc(body)}</p></div></div><details class="sample-product-details" open><summary>{esc(c["listing_details"])}</summary><dl><div><dt>{esc(c["sample_sku"])}</dt><dd>PH-00{i+1}</dd></div><div><dt>{esc(c["material"])}</dt><dd>{esc(c["materials"][i])}</dd></div><div><dt>{esc(c["size"])}</dt><dd>{esc(c["sizes"][i])}</dd></div><div><dt>{esc(c["care"])}</dt><dd>{esc(c["cares"][i])}</dd></div></dl></details><button type="button" class="btn btn-outline view-studio" data-view-studio="{i}" hidden>{esc(c["view_studio"])}{icon("arrow")}</button>'
  elif index == 1 and i == 0:
   detail=''.join(f'<div class="sample-order" data-studio-product="{j}"><div class="sample-order-head"><div><span class="mini-kicker">{esc(c["scenes"][1][0][0])} · {esc(c["studio_label"])}</span><strong>{esc(name)}</strong></div><span class="pill">{esc(c["product_status"])}</span></div><div class="sample-order-item"><span class="sample-order-art demo-product-art art-{j}" aria-hidden="true"><i class="{shape}"></i></span><span class="sample-order-name">{esc(body)}<small>{esc(c["sample_sku"])} · PH-00{j+1}</small></span><span>{esc(c["sample_prices"][j])}</span></div><dl class="sample-studio-listing"><div><dt>{esc(c["material"])}</dt><dd>{esc(c["materials"][j])}</dd></div><div><dt>{esc(c["size"])}</dt><dd>{esc(c["sizes"][j])}</dd></div><div><dt>{esc(c["care"])}</dt><dd>{esc(c["cares"][j])}</dd></div></dl></div>' for j,(name,shape) in enumerate(zip(c["store_items"],("object-cup","object-bowl","object-basket"))))
  elif index == 1:
   status=c['order_status'] if i == 1 else c['order_preparing']
   note=c['order_follow'] if i == 1 else c['order_preparing_note']
   flow=''.join(f'<li'+(' aria-current="step"' if step == i else '')+f'>{esc(label)}</li>' for step,label in ((1,c['order_status']),(2,c['order_preparing'])))
   handoff=''.join(f'<li>{esc(step)}</li>' for step in c["handoff_steps"])
   detail=f'<div class="sample-order" aria-label="{esc(c["order_title"])}"><div class="sample-order-head"><div><span class="mini-kicker">{esc(c["order_title"])}</span><strong>#PS-0124</strong></div><span class="pill">{esc(status)}</span></div><div class="sample-order-item"><span class="sample-order-art" aria-hidden="true"><i class="object-cup"></i></span><span class="sample-order-name">{esc(c["order_items"])}<small>{esc(c["sample_sku"])} · PH-001</small></span><span>RM 79.80</span></div><dl><div><dt>{esc(c["order_subtotal"])}</dt><dd>RM 79.80</dd></div><div><dt>{esc(c["order_delivery"])}</dt><dd>RM 8.00</dd></div><div class="sample-order-total"><dt>{esc(c["order_total"])}</dt><dd>RM 87.80</dd></div></dl><p class="sample-order-next">{esc(note)} · {esc(c["studio_label"])}</p><div class="sample-fulfilment"><span class="mini-kicker">{esc(c["fulfilment"])}</span><strong>{esc(c["delivery_method"])}</strong><p>{esc(c["order_tasks"][i-1])}</p></div><div class="sample-order-progress"><span class="mini-kicker">{esc(c["order_flow"])}</span><ol>{flow}</ol></div><details class="sample-handoff"><summary>{esc(c["handoff"])}</summary><p>{esc(c["handoff_intro"])}</p><ul>{handoff}</ul><p>{esc(c["handoff_note"])}</p></details></div>'
  else:
   detail=f'<strong>{esc(title)}</strong><p>{esc(body)}</p>'
  panels.append(f'<div class="scene-detail" id="scene-{index}-{i}" data-scene-detail="{i}">{detail}</div>')
 controls=f'<div class="scene-buttons" data-scene-buttons hidden>{buttons}</div>' if buttons else ''
 hint=f'<p class="scene-hint">{esc(c["scene_hint"])}</p>' if index == 1 else ''
 return f'<div class="scene-switch" data-scene-switch data-scene-kind="{index}" data-selected-label="{esc(c["selected_sample"])}"><p class="mini-kicker">{esc(c["scene_label"])}</p>{hint}{controls}<div class="scene-details">{"".join(panels)}</div><p class="visually-hidden" role="status" aria-live="polite" aria-atomic="true" data-scene-status></p></div>'

def second_order_story(c):
 order = SECOND_ORDER
 subtotal = order['unit'] * order['quantity']
 total = subtotal + order['delivery']
 money = lambda value: f'RM {value:.2f}'
 item = f'{c["store_items"][order["product"]]} × {order["quantity"]}'
 rows = ((c['unit_price'], money(order['unit'])), (c['quantity'], str(order['quantity'])), (c['order_subtotal'], money(subtotal)), (c['order_delivery'], money(order['delivery'])), (c['order_total'], money(total)))
 amounts = ''.join(f'<div><dt>{esc(label)}</dt><dd>{esc(value)}</dd></div>' for label,value in rows)
 def view(label, seller):
  checks = ''.join(f'<label><input type="checkbox" data-prep-check disabled><span>{esc(text)}</span></label>' for text in c['prep_checks'])
  action = f'<p class="order-pickup-task">{esc(c["seller_task"])}</p><fieldset class="pickup-checklist"><legend>{esc(c["prep_title"])}</legend><p>{esc(c["prep_intro"])}</p><noscript><p>{esc(c["prep_nojs"])}</p></noscript>{checks}<p class="pickup-practice-note">{esc(c["prep_note"])}</p></fieldset>' if seller else ''
  return f'<article class="order-perspective" data-order-view="{"seller" if seller else "customer"}"><p class="mini-kicker">{esc(label)} · {esc(c["studio_label"])}</p><div class="order-perspective-head"><div><span>{esc(c["order_ref"])}</span><h3>#{order["id"]}</h3></div><span class="pill" data-pickup-status>{esc(c["order_preparing"])}</span></div><div class="order-perspective-item"><span class="sample-order-art demo-product-art art-1" aria-hidden="true"><i class="object-bowl"></i></span><div><strong>{esc(item)}</strong><small>{esc(c["sample_sku"])} · {order["sku"]}</small></div></div><dl>{amounts}</dl><div class="order-pickup"><strong>{esc(c["pickup"])}</strong><p>{esc(c["pickup_note"])}</p>{action}</div></article>'
 return f'<section class="section order-story" data-pickup-example data-preparing="{esc(c["order_preparing"])}" data-ready="{esc(c["prep_ready"])}"><div class="wrap"><div class="order-story-intro"><div><p class="eyebrow">{esc(c["order_kicker"])}</p><h2>{esc(c["order_heading"])}</h2></div><p>{esc(c["order_intro"])}</p></div><div class="order-perspectives">{view(c["customer_view"],False)}{view(c["seller_view"],True)}</div><p class="order-story-note">{esc(c["order_disclaimer"])}</p><p class="visually-hidden" role="status" aria-live="polite" data-pickup-announcement></p></div></section>'

def future_concept(c):
 return f'<section class="section future-section"><div class="wrap future-layout"><div class="future-copy"><p class="eyebrow">{esc(c["future_tag"])}</p><h2>{esc(c["future_title"])}</h2><p>{esc(c["future_text"])}</p></div><div class="future-card"><div class="future-card-top"><span>{icon("spark")} AI + MCP</span><span class="pill">{esc(c["future_badge"])}</span></div><div class="future-prompt">{esc(c["future_prompt"])}</div><div class="future-canvas"><span class="mini-kicker">POMELO HOME</span><strong>{esc(c["store_title"])}</strong><div class="future-swatches" aria-hidden="true"><i></i><i></i><i></i></div></div><p>{esc(c["future_note"])}</p></div></div></section>'

def product_showcase(c):
 tabs=''.join(f'<button type="button" class="showcase-tab" id="tour-tab-{i}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="tour-panel-{i}" tabindex="{0 if i==0 else -1}" data-tour-tab="{i}"><span class="showcase-tab-icon">{icon(ic)}</span><span><b>{esc(title)}</b><small>{esc(desc)}</small></span>{icon("arrow")}</button>' for i,(ic,title,desc) in enumerate(zip(('shop','panel','spark'),c['tabs'],c['tab_desc'])))
 products=''.join(f'<button type="button" class="demo-product" data-product-button="{i}" aria-pressed="{str(i==0).lower()}" aria-controls="scene-0-{i}" data-view-label="{esc(c["view_sample"])}" data-selected-label="{esc(c["selected_sample"])}" disabled><span class="demo-product-art art-{i}" aria-hidden="true"><i class="{shape}"></i></span><b>{esc(name)}</b><small>{esc(c["store_sample"])}</small><strong class="demo-product-price">{esc(c["sample_prices"][i])}</strong><span class="product-state" data-product-state hidden></span></button>' for i,(name,shape) in enumerate(zip(c['store_items'],('object-cup','object-bowl','object-basket'))))
 shop=f'<div class="tour-shop"><div class="tour-shop-nav"><b>{esc(c["store_brand"])}</b><span>{esc(c["sample_label"])}</span></div><div class="tour-shop-hero"><div class="tour-shop-hero-copy"><span class="mini-kicker">{esc(c["store_kicker"])}</span><h3>{esc(c["store_title"])}</h3><p>{esc(c["store_desc"])}</p><a class="tour-shop-action" href="#sample-collection">{esc(c["store_action"])}</a></div><img src="{ASSET}homeware-still.webp" alt="" loading="lazy"></div><div class="collection-heading" id="sample-collection"><b>{esc(c["store_sample"])}</b><span data-product-hint hidden>{esc(c["choose_product"])}</span><noscript><span>{esc(c["collection_nojs"])}</span></noscript></div><div class="tour-products">{products}</div></div>'
 studio=f'<div class="tour-studio"><div class="tour-studio-bar"><b>Seller Studio</b><span class="pill">{esc(c["studio_label"])}</span></div><div class="tour-studio-body"><p class="mini-kicker">{esc(c["studio_kicker"])}</p><h3>{esc(c["studio_title"])}</h3><p>{esc(c["studio_desc"])}</p></div></div>'
 ai=f'<div class="tour-ai"><div class="tour-ai-head"><span class="tour-ai-icon">{icon("spark")}</span><div><b>AI + MCP</b><small>{esc(c["ai_kicker"])}</small></div><span class="pill">{esc(c["studio_label"])}</span></div><div class="tour-ai-body"><div class="tour-message tour-message-user">{esc(c["ai_prompt"])}</div><div class="tour-message tour-message-answer"><b>{esc(c["tabs"][2])}</b><p>{esc(c["ai_answer"])}</p></div><span class="tour-review">{icon("panel")}{esc(c["ai_human"])}</span><p class="tour-ai-note">{esc(c["ai_note"])}</p></div></div>'
 panels=''.join(f'<section class="showcase-panel" id="tour-panel-{i}" role="tabpanel" aria-labelledby="tour-tab-{i}" tabindex="0" data-tour-panel="{i}"><div class="showcase-panel-copy"><p class="mini-kicker">{esc(c["tabs"][i])}</p><h3>{esc(title)}</h3><p>{esc(desc)}</p></div><div class="showcase-visual">{visual}{scenario_switch(c,i)}</div></section>' for i,(title,desc,visual) in enumerate(((c['store_title'],c['feature_text'][0],shop),(c['studio_title'],c['studio_desc'],studio),(c['ai_title'],c['ai_desc'],ai))))
 return f'<section class="section showcase-section" id="product-preview"><div class="wrap"><div class="showcase-intro"><div><p class="eyebrow">{esc(c["tour_tag"])}</p><h2>{esc(c["tour_title"])}</h2></div><p>{esc(c["tour_desc"])}</p></div><div class="showcase-shell" data-product-tour><div class="showcase-tabs" role="tablist" aria-label="{esc(c["tour_tag"])}" aria-orientation="vertical" data-tour-tabs hidden>{tabs}</div><div class="showcase-panels">{panels}</div></div><p class="showcase-disclaimer">{esc(c["tour_note"])}</p></div></section>'
def home(c):
 band=''.join(f'<div><strong>{esc(n)}</strong>{esc(d)}</div>' for n,d in zip(c['band'],c['band_desc']))
 audience=''.join(f'<div class="audience"><span>{i:02}</span><b>{esc(n)}</b><p>{esc(d)}</p></div>' for i,(n,d) in enumerate(zip(c['aud_names'],c['aud_text']),1))
 features=''.join('<li>'+esc(x)+'</li>' for x in c['features'])
 return hero(c,c['home_tag'],c['home_title'],c['home_desc'],True)+f'<div class="feature-band"><div class="wrap feature-band-inner"><b>{esc(c["home_band"])}</b><div class="band-items">{band}</div></div></div>{merchant_story(c)}{concept_home(c)}{home_ai(c)}<section class="section home-services"><div class="wrap">{section_head(c["service_tag"],c["service_title"],c["service_desc"])}{cards(c["service_names"],c["service_text"],["shop","code","spark"],["commerce","services","services"],c)}</div></section><section class="section"><div class="wrap">{section_head(c["aud_tag"],c["aud_title"])}<div class="audiences">{audience}</div></div></section>'+cta(c)
def commerce(c):
 return hero(c,c['commerce_tag'],c['commerce_title'],c['commerce_desc'],variant='commerce')+f'{product_showcase(c)}{second_order_story(c)}{future_concept(c)}<section class="section"><div class="wrap">{section_head(c["product_tag"],c["product_title"])}{cards(c["feature_names"],c["feature_text"],["shop","panel","spark"])}</div></section><section class="section section-soft"><div class="wrap">{section_head(c["how_tag"],c["commerce_steps"],c["commerce_steps_desc"])}{steps(c)}<p style="margin-top:2rem">{button(c["nav"][2],link("how-it-works"),"outline")}</p></div></section>'+cta(c)
def how(c):
 items=''.join(f'<article class="journey-item" id="step-{i}"><span class="journey-num">{i:02}</span><div><h2>{esc(n)}</h2><p>{esc(d)}</p></div><div class="journey-art"><div class="dashboard"><div class="card-head"><span>{esc(short)}</span><span class="pill">{esc(c["examples"])}</span></div><div class="mock-row"><span class="mock-icon">{icon(ic)}</span><b>{esc(n)}</b></div><p class="dashboard-note">{esc(c["dash_note"])}</p></div></div></article>' for i,(n,d,short,ic) in enumerate(zip(c['steps'],c['step_text'],c['step_short'],('chat','shop','panel','spark')),1))
 faq=''.join(f'<details class="card"><summary><b>{esc(q)}</b></summary><p>{esc(a)}</p></details>' for q,a in zip(c['faq_q'],c['faq_a']))
 return hero(c,c['how_tag'],c['how_title'],c['how_desc'],variant='how')+f'<section class="section"><div class="wrap journey">{items}</div></section><section class="section section-soft"><div class="wrap">{section_head("FAQ",c["faq_title"])}<div class="stack">{faq}</div></div></section>'+cta(c)
def services(c): return hero(c,c['services_tag'],c['services_title'],c['services_desc'],variant='services')+f'<section class="section" id="service-offerings"><div class="wrap">{section_head(c["services_tag"],c["service_title"])}{cards(c["services_cards"],c["services_copy"],["panel","code","spark"])}</div></section><section class="section section-soft"><div class="wrap">{section_head(c["process_tag"],c["process_title"])}{steps(c,"process_names","process_text")}</div></section>'+cta(c)
def about(c): return hero(c,c['about_tag'],c['about_title'],c['about_desc'],variant='about')+f'<section class="section section-soft"><div class="wrap split"><div class="stack"><p class="eyebrow">{esc(c["about_tag"])}</p><h2>{esc(c["belief_title"])}</h2><p>{esc(c["belief_text"])}</p><div>{button(c["explore"],link("commerce"),"outline")}</div></div><div class="visual-panel">{brand_relation(c)}</div></div></section><section class="section"><div class="wrap"><div class="cards">'+''.join(f'<article class="card"><p class="eyebrow">{esc(k)}</p><h3>{esc(t)}</h3></article>' for k,t in ((c['mission'],c['mission_text']),(c['vision'],c['vision_text']),(c['about_work'],c['about_work_text'])))+f'</div><p class="notice" style="margin-top:1rem">{esc(c["draft_note"])}</p></div></section><section class="section section-soft"><div class="wrap">{section_head(c["process_tag"],c["process_title"])}{steps(c,"process_names","process_text")}</div></section>'+cta(c)
def contact(c):
 fields=''.join(f'<label>{esc(c[key])}<input type="{typ}" name="{key}"></label>' for key,typ in [('name','text'),('shop','text'),('email','email'),('phone','tel')])
 wa='https://wa.me/601139023123'
 follow=''.join(f'<article class="step"><span class="step-number">{i:02}</span><h3>{esc(n)}</h3><p>{esc(d)}</p></article>' for i,(n,d) in enumerate(zip(c['next_names'],c['next_text']),1))
 return hero(c,c['contact_tag'],c['contact_title'],c['contact_desc'],variant='contact')+f'<section class="section section-soft"><div class="wrap contact-layout"><div class="stack"><p class="eyebrow">WHATSAPP</p><h2>{esc(c["whatsapp"])}</h2><p>{esc(c["whatsapp_desc"])}</p><p><strong>+60 11-3902 3123</strong></p><div>{button(c["whatsapp"],wa)}</div></div><div id="sample-form" class="contact-card stack"><div class="form-heading"><div><p class="eyebrow">{esc(c["sample_label"])}</p><h2>{esc(c["sample_contact_title"])}</h2></div><span class="form-icon">{icon("chat")}</span></div><p class="notice">{esc(c["sample_form"])}</p><form class="form-grid" data-demo-form data-result="{esc(c["sample_result"])}" autocomplete="off"><fieldset disabled data-demo-fields>{fields}<label>{esc(c["interest"])}<select name="interest"><option>Pomelo Commerce</option><option>{esc(c["demo_field"])}</option><option>{esc(c["services_tag"])}</option></select></label><label>{esc(c["message"])}<textarea name="message"></textarea></label><button class="btn btn-primary" type="submit">{esc(c["sample_submit"])} {icon("arrow")}</button></fieldset><p class="form-result" role="status" data-demo-result hidden></p><noscript><p class="notice">{esc(c["sample_nojs"])}</p></noscript></form></div></div></section><section class="section"><div class="wrap">{section_head(c["contact_tag"],c["sample_next"])}<div class="steps">{follow}</div></div></section>'+cta(c,True)
RENDERERS={'index':home,'commerce':commerce,'how-it-works':how,'services':services,'about':about,'contact':contact}
def render(lang,page):
 global ASSET
 c=COPY[lang]; base=rel(lang); ASSET=base+'assets/'
 nav=''.join(f'<a href="{link(p)}"'+(' aria-current="page"' if page==p else '')+f'>{esc(n)}</a>' for p,n in zip(PAGES,c['nav']))
 langs=''.join(f'<a data-locale="{code}" href="{esc(("../" if lang!="en" else "./")+("" if code=="en" else code+"/")+page+".html")}"'+(' aria-current="true"' if code==lang else '')+f'>{esc(name)}</a>' for code,name in [('en','English'),('zh','简体中文'),('ms','Bahasa Melayu')])
 foot=''.join(f'<a href="{link(p)}">{esc(n)}</a>' for p,n in zip(PAGES,c['nav']))
 control=(f'<details class="panel"><summary aria-label="{esc(c["lang"])}" title="{esc(c["lang"])}">{icon("language")}<span class="language-code">{esc(lang.upper())}</span></summary><div class="panel-menu">{langs}</div></details>'
 f'<button class="control" type="button" data-theme-toggle data-dark="{esc(c["dark"])}" data-light="{esc(c["light"])}" aria-label="{esc(c["dark"])}" title="{esc(c["dark"])}">{icon("sun")}</button>'
 f'<details class="panel" data-update data-version="{VERSION}" data-manifest="{base}release.json" data-checking="{esc(c["checking"])}" data-current="{esc(c["current"])}" data-available="{esc(c["available"])}" data-error="{esc(c["error"])}" data-confirm="{esc(c["confirm"])}" data-updated="{esc(c["updated"])}" data-unverified="{esc(c["unverified"])}"><summary aria-label="{esc(c["update"])}" title="{esc(c["update"])}">{icon("update")}<span class="version">{VERSION}</span></summary><div class="panel-menu"><p>{esc(c["update"])} · v{VERSION}</p><p data-status role="status">{esc(c["checking"])}</p><button data-retry type="button">{esc(c["retry"])}</button><button data-apply type="button" hidden>{esc(c["apply"])}</button><noscript><p>{esc(c["error"])}</p></noscript></div></details>'
 f'<details class="panel mobile-panel"><summary aria-label="{esc(c["menu"])}">{icon("menu")}</summary><nav class="panel-menu mobile-nav" aria-label="{esc(c["menu"])}">{nav}</nav></details>')
 doclang={'en':'en','zh':'zh-Hans','ms':'ms'}[lang]
 return f'''<!doctype html>
<html lang="{doclang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="robots" content="noindex,nofollow"><meta name="pomelo-version" content="{VERSION}"><title>{esc(c['nav'][PAGES.index(page)])} | Pomelo STEM</title><script src="{ASSET}boot.js?v={VERSION}"></script><link rel="stylesheet" href="{ASSET}site.css?v={VERSION}"><script defer src="{ASSET}app.js?v={VERSION}"></script><script defer src="{ASSET}update.js?v={VERSION}"></script></head>
<body><div class="loader" aria-hidden="true"><div><img src="{ASSET}pomelo-compact.svg" alt=""><span>{esc(c['loading'])}</span></div></div><a class="skip" href="#main">{esc(c['skip'])}</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{link('index')}"><img src="{ASSET}pomelo-compact.svg" alt=""><span>POMELO STEM</span></a><nav class="desktop-nav" aria-label="{esc(c['menu'])}">{nav}</nav><div class="controls">{control}</div>{button(c['cta'],link('contact')) .replace('class="btn btn-primary"','class="btn btn-primary header-cta"')}</div></header>
<main id="main"{' class="home-page"' if page == 'index' else ''}>{RENDERERS[page](c)}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="{link('index')}"><img src="{ASSET}pomelo-compact.svg" alt=""><span>POMELO STEM</span></a><p>{esc(c['tagline'])}</p></div><div><h3>{esc(c['solutions'])}</h3>{foot}</div><div><h3>{esc(c['company'])}</h3><a href="https://wa.me/601139023123">WhatsApp<br>+60 11-3902 3123</a><a href="https://pomelostem.com/">pomelostem.com</a></div></div><div class="footer-bottom"><span>© 2026 Pomelo STEM · Malaysia &amp; Singapore</span><span>{esc(c['footer_note'])}</span></div></div></footer></body></html>\n'''

def main():
 for lang in COPY:
  for page in PAGES:
   target=OUT / ('' if lang=='en' else lang) / (page+'.html')
   target.parent.mkdir(parents=True,exist_ok=True)
   target.write_text(render(lang,page),encoding='utf-8')
 print('Generated',len(COPY)*len(PAGES),'V7 pages')
if __name__=='__main__': main()
